import {createSceneStore} from './scene-library-store.mjs';
import {dragScroll} from './drag-scroll.mjs';
export function installSceneLibrary({capture,load,newRanch,busy,describe,render,instances,flush,removeInstance,defaultName}){
 const store=createSceneStore(localStorage);let revision=0,working=false,manage=false,lastRemoved=null,lastIdentity='';
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./scene-library.css',import.meta.url);document.head.append(css);
 const drawer=document.createElement('dialog');drawer.id='saved-scenes';drawer.setAttribute('aria-labelledby','saved-scenes-title');drawer.innerHTML=`<div class="saved-heading"><h2 id="saved-scenes-title">Scenes</h2><button id="saved-close" aria-label="Close scenes">×</button></div><div class="saved-toolbar"><details id="saved-new-menu"><summary>New ＋</summary><button id="saved-new">New ranch</button><button id="saved-copy">Copy current scene</button></details><button id="saved-manage" aria-pressed="false">Manage</button></div><input id="saved-search" type="search" aria-label="Search scenes" placeholder="Find a scene…"><label class="saved-check"><input id="saved-favorites" type="checkbox">Favorites</label><div id="saved-list" role="table" aria-label="Saved scenes"></div><div class="saved-footer" hidden><button id="saved-import">Import</button><input id="saved-file" type="file" accept="application/json,.json" hidden><button id="saved-undo" hidden>Undo remove</button></div><p class="saved-scope">Autosaved in this browser</p><p id="saved-status" role="status" aria-live="polite"></p>`;document.body.append(drawer);
 dragScroll(drawer.querySelector('#saved-list'),{snap:'.saved-row'});
 const $=s=>drawer.querySelector(s),opener=document.querySelector('#compact-scene-title');opener.setAttribute('aria-haspopup','dialog');opener.setAttribute('aria-controls',drawer.id);
 function notify(message){$('#saved-status').textContent=message;revision++;window.RanchView?.changed('Scene library');}
 const build=()=>window.RanchView?.actionTarget?.().buildId;
 function sync(){try{const id=describe().instanceId,i=instances().find(i=>i.id===id);if(!i?.snapshot)return;store.autosave(i.id,defaultName(i),{...i,...capture()},build());const identity=i.id+':'+i.config.seed;if(identity!==lastIdentity){lastIdentity=identity;revision++;window.RanchView?.changed('Scene autosaved');}syncTitle();}catch(e){notify('Autosave unavailable: '+e.message);}}
 for(const i of instances()){if(!i.snapshot)continue;try{store.read(i.id);}catch{try{store.autosave(i.id,defaultName(i),i,build());}catch{}}}
 function syncTitle(){let entry;try{entry=store.read(describe().instanceId);}catch{}if(entry){opener.firstElementChild.textContent=entry.name;opener.setAttribute('aria-label',entry.name+': browse scenes');}}
 new MutationObserver(syncTitle).observe(document.querySelector('.live-status'),{childList:true,subtree:true,characterData:true});
 window.addEventListener('sandbox-autosaved',sync);
 for(const event of ['change','pointerup','wheel'])document.addEventListener(event,e=>{if(e.isTrusted&&!drawer.contains(e.target)&&!e.target.closest?.('#developer-overlay')){revision++;window.RanchView?.changed('Working scene edited');}},{capture:true,passive:true});
 function summaries(){const result=store.list();return {...result,entries:result.entries.map(({scene,...entry})=>({...entry,family:scene.family,seed:scene.config.seed,preset:scene.config.preset}))};}
 function read(){return {version:2,revision,storageScope:'this browser',open:drawer.open,busy:working||busy(),current:describe(),...summaries()};}
 async function perform(fn){if(working||busy())throw Error('Wait for the current scene interaction to finish.');working=true;try{return await fn();}finally{working=false;refresh();syncTitle();}}
 function save({name}){return copy({sceneId:describe().instanceId,name});}
 function favorite({sceneId,value}){return perform(()=>{const e=store.favorite(sceneId,value);notify(value?'Favorited':'Favorite removed');return {sceneId,sceneRevision:e.revision,state:read()};});}
 function restore({sceneId}){return perform(async()=>{const e=store.read(sceneId);if(e.removed)throw Error('Scene was removed.');await load(e.scene,e.name,e.id);notify('Opened '+e.name);drawer.close();return {sceneId,sceneRevision:e.revision,state:read()};});}
 function copy({sceneId,name}){return perform(async()=>{flush();const source=store.read(sceneId),entry=store.save(name||source.name+' copy',source.scene,build());await load(entry.scene,entry.name,entry.id);notify('Copied '+source.name);drawer.close();return {sceneId:entry.id,sceneRevision:entry.revision,state:read()};});}
 function rename({sceneId,name}){return perform(()=>{const e=store.update(sceneId,{name:name.trim()});notify('Renamed');return {sceneId,sceneRevision:e.revision,state:read()};});}
 function remove({sceneId}){return perform(async()=>{if(sceneId===describe().instanceId)throw Error('Open another scene before removing this one.');store.update(sceneId,{removed:true});removeInstance(sceneId);lastRemoved=sceneId;$('#saved-undo').hidden=false;notify('Removed · Undo is available');return {sceneId,state:read()};});}
 function undoRemove({sceneId}){return perform(()=>{store.update(sceneId,{removed:false});lastRemoved=null;$('#saved-undo').hidden=true;notify('Scene restored');return {sceneId,state:read()};});}
 function exportScene({sceneId}){return {sceneId,artifact:store.read(sceneId)};}
 function importScene({json}){return perform(()=>{const e=store.importScene(json);notify('Imported '+e.name);return {sceneId:e.id,state:read()};});}
 function fresh(){return perform(async()=>{await newRanch();sync();notify('New ranch');drawer.close();return {state:read()};});}
 const run=fn=>Promise.resolve().then(fn).catch(e=>notify(e.message));
 function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=()=>run(fn);return b;}
 function refresh(){const data=summaries(),query=$('#saved-search').value.trim().toLowerCase(),favorites=$('#saved-favorites').checked,list=$('#saved-list');list.replaceChildren();for(const e of data.entries){if(favorites&&!e.favorite||query&&!`${e.name} ${e.family} ${e.seed}`.toLowerCase().includes(query))continue;const row=document.createElement('div');row.className='saved-row';row.setAttribute('role','row');row.classList.toggle('is-current',e.id===describe().instanceId);const star=button(e.favorite?'★':'☆',()=>favorite({sceneId:e.id,value:!e.favorite}));star.setAttribute('aria-label','Favorite '+e.name);star.setAttribute('aria-pressed',String(e.favorite));const cell=document.createElement('div');cell.className='saved-scene-cell';const title=button(e.name,()=>{if(!manage)return restore({sceneId:e.id});const input=document.createElement('input');input.value=e.name;input.maxLength=100;input.setAttribute('aria-label','Rename '+e.name);title.replaceWith(input);input.focus();input.select();let done=false;const commit=()=>{if(done)return;done=true;run(()=>rename({sceneId:e.id,name:input.value}));};input.onblur=commit;input.onkeydown=event=>{if(event.key==='Enter')commit();if(event.key==='Escape'){done=true;refresh();}};});const meta=document.createElement('small');meta.textContent=`${e.family} · ${e.id===describe().instanceId?'✓ Open · ':''}Seed ${e.seed}`;cell.append(title,meta);row.append(star,cell);if(manage){const actions=document.createElement('div');actions.className='saved-row-actions';actions.append(button('Copy',()=>copy({sceneId:e.id})),button('Remove',()=>remove({sceneId:e.id})),button('Export',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(exportScene({sceneId:e.id}).artifact)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=e.name+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}));row.append(actions);}list.append(row);}if(!list.children.length)list.textContent='No scenes match.';if(data.errors.length)notify(data.errors.join(' '));}
 // Only one side panel at a time: the tile tools step aside while Scenes is open and return when it closes.
 opener.onclick=()=>{flush();syncTitle();refresh();for(const p of document.querySelectorAll('[popover]:popover-open'))p.hidePopover();document.body.classList.add('scene-library-open');drawer.showModal();opener.setAttribute('aria-expanded','true');};drawer.onclose=()=>{document.body.classList.remove('scene-library-open');opener.setAttribute('aria-expanded','false');};drawer.addEventListener('click',e=>{if(e.target!==drawer)return;const r=drawer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)drawer.close();});$('#saved-close').onclick=()=>drawer.close();$('#saved-search').oninput=refresh;$('#saved-favorites').onchange=refresh;$('#saved-manage').onclick=()=>{manage=!manage;$('#saved-manage').setAttribute('aria-pressed',String(manage));$('.saved-footer').hidden=!manage;refresh();};$('#saved-new').onclick=()=>run(fresh);$('#saved-copy').onclick=()=>run(()=>copy({sceneId:describe().instanceId}));$('#saved-undo').onclick=()=>run(()=>undoRemove({sceneId:lastRemoved}));$('#saved-import').onclick=()=>$('#saved-file').click();$('#saved-file').onchange=()=>run(async()=>{const f=$('#saved-file').files[0];if(f)await importScene({json:await f.text()});});
 window.addEventListener('storage',e=>{if(e.key?.startsWith('abbies-sandbox-scene-v1:')){revision++;if(drawer.open)refresh();syncTitle();}});
 window.RanchView?.register('sandboxScenes',read,render);
 const schema=(properties={},required=[])=>({type:'object',properties,required,additionalProperties:false}),id={type:'string'};
 window.RanchActions?.register('sandboxScenes',{revision:()=>revision,read,unavailable:action=>!['list','export'].includes(action)&&(working||busy())?'Scene is busy':null,actions:{list:{description:'Browse autosaved scenes',schema:schema(),readOnly:true,run:read},save:{description:'Copy current scene with a name',schema:schema({name:id},['name']),run:save},load:{description:'Open an autosaved scene',schema:schema({sceneId:id},['sceneId']),run:restore},copy:{description:'Copy a scene independently',schema:schema({sceneId:id},['sceneId']),run:copy},rename:{description:'Rename a scene',schema:schema({sceneId:id,name:id},['sceneId','name']),run:rename},remove:{description:'Remove an inactive scene',schema:schema({sceneId:id},['sceneId']),run:remove},undoRemove:{description:'Restore a removed scene',schema:schema({sceneId:id},['sceneId']),run:undoRemove},favorite:{description:'Set favorite',schema:schema({sceneId:id,value:{type:'boolean'}},['sceneId','value']),run:favorite},export:{description:'Export scene',schema:schema({sceneId:id},['sceneId']),readOnly:true,run:exportScene},import:{description:'Import scene',schema:schema({json:id},['json']),run:importScene},newRanch:{description:'Create vanilla ranch',schema:schema(),run:fresh}}});syncTitle();return {read};
}
